(1382, 'wppb-ul-templates', '\r\n<table class=\"wppb-table\">\r\n	<thead>\r\n		<tr>\r\n		  <th scope=\"col\" colspan=\"2\" class=\"wppb-sorting\">{{{sort_user_name}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_first_name}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_role}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_number_of_posts}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_registration_date}}}</th>\r\n		  <th scope=\"col\">More</th>\r\n		</tr>\r\n	</thead>	\r\n	<tbody>\r\n		{{#users}}\r\n		<tr>\r\n		  <td data-label=\"Аватар\" class=\"wppb-avatar\">{{{avatar_or_gravatar}}}</td>\r\n		  <td data-label=\"Имя пользователя\" class=\"wppb-login\">{{meta_user_name}}</td>\r\n		  <td data-label=\"Имя\" class=\"wppb-name\">{{meta_first_name}} {{meta_last_name}}</td>\r\n		  <td data-label=\"Ранг\" class=\"wppb-role\">{{meta_role}}</td>\r\n		  <td data-label=\"Сообщений\" class=\"wppb-posts\">{{{meta_number_of_posts}}}</td>\r\n		  <td data-label=\"Дата регистрации\" class=\"wppb-signup\">{{meta_registration_date}}</td>\r\n		  <td data-label=\"Больше\" class=\"wppb-moreinfo\">{{{more_info}}}</td>\r\n		</tr>\r\n		{{/users}}\r\n	</tbody>\r\n</table>\r\n{{{pagination}}}', 'yes'),
(1383, 'wppb-single-ul-templates', '\r\n{{{extra_go_back_link}}}\r\n<ul class=\"wppb-profile\">\r\n  <li>\r\n    <h3>Name</h3>\r\n  </li>\r\n  <li class=\"wppb-avatar\">\r\n    {{{avatar_or_gravatar}}}\r\n  </li>\r\n  <li>\r\n    <label>Username:</label>\r\n    <span>{{meta_user_name}}</span>\r\n  </li>\r\n  <li>\r\n    <label>First Name:</label>\r\n    <span>{{meta_first_name}}</span>\r\n  </li>\r\n  <li>\r\n    <label>Last Name:</label>\r\n    <span>{{meta_last_name}}</span>\r\n  </li>\r\n  <li>\r\n    <label>Nickname:</label>\r\n    <span>{{meta_nickname}}</span>\r\n  </li>\r\n  <li>\r\n    <label>Display name:</label>\r\n	<span>{{meta_display_name}}</span>\r\n  </li>\r\n  <li>\r\n    <h3>Contact Info</h3>\r\n  </li>\r\n  <li>\r\n  	<label>Website:</label>\r\n	<span>{{meta_website}}</span>\r\n  </li>\r\n  <li>\r\n    <h3>About Yourself</h3>\r\n  </li>\r\n  <li>\r\n	<label>Biographical Info:</label>\r\n	<span>{{{meta_biographical_info}}}</span>\r\n  </li>\r\n</ul>\r\n{{{extra_go_back_link}}}', 'yes'),
(1384, 'external_updates-profile-builder-pro-update', 'O:8:\"stdClass\":3:{s:9:\"lastCheck\";i:1540509723;s:14:\"checkedVersion\";s:5:\"2.9.0\";s:6:\"update\";O:12:\"PluginUpdate\":6:{s:2:\"id\";i:0;s:4:\"slug\";s:26:\"profile-builder-pro-update\";s:7:\"version\";s:5:\"2.9.1\";s:8:\"homepage\";N;s:12:\"download_url\";s:82:\"https://www.cozmoslabs.com/wp-content/plugins/cl_serve_download.php?tempkey=138100\";s:14:\"upgrade_notice\";N;}}', 'yes'),
