(1391, 'wppb_module_settings', 'a:6:{s:30:\"wppb_multipleRegistrationForms\";s:4:\"show\";s:29:\"wppb_multipleEditProfileForms\";s:4:\"show\";s:16:\"wppb_userListing\";s:4:\"show\";s:20:\"wppb_emailCustomizer\";s:4:\"show\";s:19:\"wppb_customRedirect\";s:4:\"show\";s:19:\"wppb_repeaterFields\";s:4:\"show\";}', 'yes'),
(1393, 'wppb_module_settings_description', 'a:6:{s:16:\"wppb_userListing\";s:12:\"User-Listing\";s:19:\"wppb_customRedirect\";s:16:\"Custom Redirects\";s:20:\"wppb_emailCustomizer\";s:16:\"Email Customizer\";s:29:\"wppb_multipleEditProfileForms\";s:18:\"Edit-profile Forms\";s:30:\"wppb_multipleRegistrationForms\";s:18:\"Registration Forms\";s:19:\"wppb_repeaterFields\";s:15:\"Repeater Fields\";}', 'yes'),
(1397, 'wppb_admin_emailc_common_settings_header', 'Эти настройки также переносятся на страницу настроек \"Настройщика электронной почты пользователя\" после сохранения. Существующие тэги {{reply_to}} и {{site_name}}', 'yes'),
(1398, 'wppb_emailc_common_settings_from_name', '{{site_name}}', 'yes'),
(1399, 'wppb_emailc_common_settings_from_reply_to_email', '{{reply_to}}', 'yes'),
(1400, 'wppb_admin_emailc_default_registration_email_subject', '[{{site_name}}] Новый абонент (был) зарегистрирован!', 'yes'),
(1401, 'wppb_admin_emailc_default_registration_email_content', '<p>New subscriber on {{site_name}}.</p>\n<p>Username:{{username}}</p>\n<p>E-mail:{{user_email}}</p>\n', 'yes'),
(1402, 'wppb_admin_emailc_registration_with_admin_approval_email_subject', '[{{site_name}}] A new subscriber has (been) registered!', 'yes'),
(1403, 'wppb_admin_emailc_registration_with_admin_approval_email_content', '<p>New subscriber on {{site_name}}.</p>\n<p>Username:{{username}}</p>\n<p>E-mail:{{user_email}}</p>\n<p>The Admin Approval feature was activated at the time of registration,\nso please remember that you need to approve this user before he/she can log in!</p>', 'yes'),
(1404, 'wppb_admin_emailc_user_password_reset_email_subject', '[{{site_name}}] Password Successfully Reset for {{username}}', 'yes'),
(1405, 'wppb_admin_emailc_user_password_reset_email_content', '<p>{{username}} has requested a password change via the password reset feature.</p>\n<p>His/her new password is: {{password}}</p>\n', 'yes'),
(1406, 'wppb_user_emailc_default_registration_email_subject', 'A new account has been created for you on {{site_name}}', 'yes'),
(1407, 'wppb_user_emailc_default_registration_email_content', '<h3>Welcome to {{site_name}}!</h3>\r\n<p>Your username is:{{user_email}} and password:{{password}}</p>\r\n', 'yes'),
(1408, 'wppb_user_emailc_registr_w_email_confirm_email_subject', '[{{site_name}}] Активировать {{user_email}}', 'yes'),
(1409, 'wppb_user_emailc_registr_w_email_confirm_email_content', '<p>To activate your user, please click the following link:<br/>\r\n{{{activation_link}}}</p>\r\n<p>After you activate, you will receive another email with your credentials.</p>\r\n', 'yes'),
(1410, 'wppb_user_emailc_registration_with_admin_approval_email_subject', 'Новая учетная запись была создана для вас на {{site_name}}', 'yes'),
(1411, 'wppb_user_emailc_registration_with_admin_approval_email_content', '<h3>Welcome to {{site_name}}!</h3>\r\n<p>Your username is:{{username}} and password:{{password}}</p>\r\n<p>Before you can access your account, an administrator needs to approve it. You will be notified via email.</p>\r\n', 'yes'),
(1412, 'wppb_user_emailc_admin_approval_notif_approved_email_subject', 'Ваша учётная запись на {{site_name}} была одобрена!', 'yes'),
(1413, 'wppb_user_emailc_admin_approval_notif_approved_email_content', '<h3>Good News!</h3>\r\n<p>An administrator has just approved your account: {{username}} on {{site_name}}.</p>\r\n', 'yes'),
(1414, 'wppb_user_emailc_admin_approval_notif_unapproved_email_subject', 'Ваша учётная запись на {{site_name}} не была одобрена!', 'yes'),
(1415, 'wppb_user_emailc_admin_approval_notif_unapproved_email_content', '<h3>Hello,</h3>\r\n<p>Unfortunatelly an administrator has just unapproved your account: {{username}} on {{site_name}}.</p>\r\n', 'yes'),
(1416, 'wppb_user_emailc_reset_email_subject', '[{{site_name}}] Сброс пароля', 'yes');
INSERT INTO `wp_options` (`option_id`, `option_name`, `option_value`, `autoload`) VALUES
(1417, 'wppb_user_emailc_reset_email_content', '<p>Someone requested that the password be reset for the following account: {{site_name}}<br/>\r\nUsername: {{username}}</p>\r\n<p>If this was a mistake, just ignore this email and nothing will happen.</p>\r\n<p>To reset your password, visit the following address:<br/>\r\n{{{reset_link}}}</p>\r\n', 'yes'),
(1418, 'wppb_user_emailc_reset_success_email_subject', '[{{site_name}}] Пароль успешно сброшен', 'yes'),
(1419, 'wppb_user_emailc_reset_success_email_content', '<p>You have successfully reset your password.</p>\r\n', 'yes'),
(1420, 'wppb_user_emailc_change_email_address_subject', '[{{site_name}}] Notice of Email Change', 'yes'),
(1421, 'wppb_user_emailc_change_email_address_content', '<h3>Hi {{username}},</h3>\r\n<p>This notice confirms that your email was changed on {{site_name}}.</p>\r\n<p>If you did not change your email, please contact the Site Administrator at office@aliveliyev.com</p>\r\n<p>This email has been sent to {{user_email}}</p>\r\n<p>Regards,<br>\r\nAll at {{site_name}}<br>\r\n<a href=\"{{site_url}}\">{{site_url}}</a></p>', 'yes'),
